async function renderMessages(chat){
 const area=$("messageArea");if(!area||activeChatId!==chat.id)return;
 const mediaMessages=chat.messages.filter(message=>message.media_path&&!message.deleted_at);
 const signed=await Promise.all(mediaMessages.map(async message=>{const result=await supabase.storage.from("message-media").createSignedUrl(message.media_path,3600);return [message.id,result.error?null:result.data?.signedUrl||null]}));
 if(activeChatId!==chat.id)return;
 const urls=Object.fromEntries(signed);
 const content=message=>{
  if(message.deleted_at)return '<div class="message-deleted">This message was deleted</div>';
  const type=message.message_type||"text";
  if(type==="sticker")return '<div class="message-sticker">'+escapeHTML(message.text)+'</div>';
  if(message.media_path){const url=urls[message.id];if(!url)return '<div class="message-attachment">Attachment unavailable</div>';if(type==="image")return '<a href="'+escapeHTML(url)+'" target="_blank" rel="noopener"><img class="chat-image" src="'+escapeHTML(url)+'" alt="'+escapeHTML(message.file_name||"Shared image")+'" loading="lazy"></a>';if(type==="video")return '<video class="chat-video" src="'+escapeHTML(url)+'" controls playsinline preload="metadata"></video>';if(type==="audio")return '<audio class="chat-audio" src="'+escapeHTML(url)+'" controls preload="metadata"></audio>';return '<a class="chat-file" href="'+escapeHTML(url)+'" target="_blank" rel="noopener"><span>▤</span><span>'+escapeHTML(message.file_name||"Download attachment")+'</span></a>'}
  return message.text?'<div class="message-text">'+escapeHTML(message.text)+'</div>':'';
 };
 area.innerHTML='<div class="date-divider"><span>MESSAGES</span></div>'+chat.messages.map(message=>'<div class="message-row '+(message.mine?"mine":"")+'" data-message-id="'+message.id+'"><div class="message-bubble">'+content(message)+(message.text&&message.media_path?'<div class="message-caption">'+escapeHTML(message.text)+'</div>':'')+'</div><div class="message-meta">'+escapeHTML(message.time)+(message.mine?" · ✓":"")+'</div></div>').join("");
 area.scrollTop=area.scrollHeight;
 area.querySelectorAll("[data-message-id]").forEach(row=>{let holdTimer=null;const open=()=>showMessageActions(row.dataset.messageId);row.addEventListener("contextmenu",event=>{event.preventDefault();open()});row.addEventListener("pointerdown",event=>{if(event.pointerType==="mouse")return;holdTimer=setTimeout(open,550)});["pointerup","pointerleave","pointercancel"].forEach(name=>row.addEventListener(name,()=>clearTimeout(holdTimer)))});
}
