function subscribeRealtime(){if(realtimeChannel)supabase.removeChannel(realtimeChannel);if(!online()||!user)return;realtimeChannel=supabase.channel("lumcor-message-stream").on("postgres_changes",{event:"INSERT",schema:"public",table:"messages"},payload=>{const row=payload.new;const chat=chats.find(item=>item.id===row.conversation_id);if(!chat){loadChats().catch(()=>{});return}if(chat.messages.some(message=>message.id===row.id))return;chat.messages.push({id:row.id,text:row.body,mine:row.sender_id===user.id,time:new Date(row.created_at).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"}),created_at:row.created_at,message_type:row.message_type||"text",media_path:row.media_path,file_name:row.file_name,mime_type:row.mime_type,file_size:row.file_size});renderChats();if(activeChatId===chat.id)renderMessages(chat);cacheSet("workspace",{chats,profile})}).on("postgres_changes",{event:"UPDATE",schema:"public",table:"messages"},payload=>{const row=payload.new;const chat=chats.find(item=>item.id===row.conversation_id);const message=chat?.messages.find(item=>item.id===row.id);if(!message)return;message.deleted_at=row.deleted_at;message.text=row.deleted_at?"":row.body;message.media_path=row.deleted_at?null:row.media_path;message.file_name=row.deleted_at?null:row.file_name;if(activeChatId===chat.id)renderMessages(chat);renderChats();cacheSet("workspace",{chats,profile})}).subscribe()}
function openCreateModal(type="direct"){const group=type==="group";const modal=$("newChatModal");$("modalTitle").textContent=group?"Create a group":"Start a chat";$("contactNameLabel").textContent=group?"Group name":"Lumcor username";$("contactName").placeholder=group?"Enter a group name":"Enter their username";$("contactAbout").value="";$("contactName").value="";$("newChatFeedback").textContent="";$("createChatButton").disabled=false;modal.dataset.type=type;if(!modal.open)modal.showModal();requestAnimationFrame(()=>$("contactName").focus())}
async function createChat(event){event.preventDefault();const feedback=$("newChatFeedback");const button=$("createChatButton");const name=$("contactName").value.trim();if(!name){feedback.textContent="Enter a username or group name to continue."; $("contactName").focus();return}if(!online()){feedback.textContent="You are offline. Reconnect and try again.";return}if(!user||!supabase){feedback.textContent="Your Lumcor session is not ready. Sign in again.";return}const type=$("newChatModal").dataset.type||"direct";button.disabled=true;feedback.textContent="Please wait…";try{if(type==="group"){const created=await supabase.from("conversations").insert({kind:"group",title:name,created_by:user.id}).select("id").single();if(created.error)throw created.error;const membership=await supabase.from("conversation_members").insert({conversation_id:created.data.id,user_id:user.id,role:"owner"});if(membership.error)throw membership.error;$("newChatModal").close();await loadChats();openChat(created.data.id);showToast("Group created")}else{const result=await supabase.from("profiles").select("id,username,display_name").eq("username",name.replace(/^@/,"").toLowerCase()).maybeSingle();if(result.error)throw result.error;if(!result.data){feedback.textContent="No Lumcor account found with that username. Check the spelling and try again.";return}if(result.data.id===user.id){feedback.textContent="You cannot start a chat with your own account.";return}const a=user.id<result.data.id?user.id:result.data.id;const b=user.id<result.data.id?result.data.id:user.id;const existing=await supabase.from("connections").select("id,status,requested_by").eq("user_a",a).eq("user_b",b).maybeSingle();if(existing.error)throw existing.error;if(!existing.data){const request=await supabase.from("connections").insert({user_a:a,user_b:b,requested_by:user.id,status:"pending"});if(request.error)throw request.error;$("newChatModal").close();showToast("Connection request sent")}else if(existing.data.status==="accepted"){await createDirectConversation(result.data.id);$("newChatModal").close()}else if(existing.data.status==="pending"&&existing.data.requested_by!==user.id){const accepted=await supabase.from("connections").update({status:"accepted"}).eq("id",existing.data.id);if(accepted.error)throw accepted.error;await createDirectConversation(result.data.id);$("newChatModal").close()}else{feedback.textContent="Your connection request is still waiting for the other person to respond."}}}catch(error){feedback.textContent=error.message||"Unable to complete that action. Please try again."}finally{button.disabled=false;if(feedback.textContent==="Please wait…")feedback.textContent=""}}
async function createDirectConversation(otherId){if(!user||!otherId||otherId===user.id)throw new Error("Choose a valid Lumcor connection.");if(!online())throw new Error("Reconnect to open this conversation.");const local=chats.find(chat=>chat.type==="direct"&&chat.participants?.includes(otherId));if(local){await openChat(local.id);return}const mine=await supabase.from("conversation_members").select("conversation_id").eq("user_id",user.id);if(mine.error)throw mine.error;const ids=(mine.data||[]).map(row=>row.conversation_id);if(ids.length){const theirs=await supabase.from("conversation_members").select("conversation_id").eq("user_id",otherId).in("conversation_id",ids);if(theirs.error)throw theirs.error;const shared=[...new Set((theirs.data||[]).map(row=>row.conversation_id))];if(shared.length){const found=await supabase.from("conversations").select("id").in("id",shared).eq("kind","direct");if(found.error)throw found.error;if(found.data?.length){await loadChats();await openChat(found.data[0].id);return}}}const created=await supabase.from("conversations").insert({kind:"direct",created_by:user.id}).select("id").single();if(created.error)throw created.error;const added=await supabase.from("conversation_members").insert([{conversation_id:created.data.id,user_id:user.id,role:"owner"},{conversation_id:created.data.id,user_id:otherId,role:"member"}]);if(added.error)throw added.error;await loadChats();if(!chats.some(chat=>chat.id===created.data.id))throw new Error("The conversation was created, but its membership could not be loaded. Refresh and try again.");await openChat(created.data.id);showToast("Conversation ready")}
async function showUtility(view){document.body.classList.remove("mobile-chat-open");document.body.classList.add("mobile-utility-open");currentView=view;activeChatId=null;$("conversation").classList.add("hidden");$("welcomePanel").classList.add("hidden");$("utilityView").classList.remove("hidden");document.querySelectorAll(".rail-button[data-view]").forEach(button=>button.classList.toggle("active",button.dataset.view===view));const titles={connect:"Connect",status:"Updates",groups:"Communities",calls:"Calls",settings:"Settings",marketplace:"Marketplace"};$("topbarTitle").textContent=titles[view]||"Messages";$("sidebar").classList.remove("open");if(view==="status")await renderStatus();if(view==="groups")await renderGroups();if(view==="calls")renderCalls();if(view==="connect")await renderConnections();if(view==="settings"){const panel=$("utilityView");panel.innerHTML='<div class="settings-page"><span class="eyebrow">PERSONALISE YOUR SPACE</span><h1>Settings</h1><div class="empty-state"><strong>Loading settings…</strong>Please wait while your account preferences load.</div></div>';try{await renderSettings()}catch(error){panel.innerHTML='<div class="settings-page"><span class="eyebrow">PERSONALISE YOUR SPACE</span><h1>Settings</h1><div class="empty-state"><strong>Settings could not be loaded</strong>'+escapeHTML(error?.message||"Please check your connection and try again.")+'</div><button class="primary-button" id="retrySettingsButton" type="button">Try again</button></div>';$("retrySettingsButton").addEventListener("click",()=>showUtility("settings"))}}if(view==="marketplace")await renderMarketplace();document.querySelectorAll(".mobile-nav-item").forEach(button=>button.classList.toggle("active",button.dataset.view===view))}
async function renderConnections(){if(!online()){$("utilityView").innerHTML='<span class="eyebrow">YOUR PEOPLE</span><h1>Connect</h1><div class="empty-state"><strong>Connect to the internet</strong>Connection requests need an internet connection.</div>';return}const [a,b]=await Promise.all([supabase.from("connections").select("*").eq("user_a",user.id),supabase.from("connections").select("*").eq("user_b",user.id)]);if(a.error||b.error){showToast("Could not load connections");return}const rows=[...(a.data||[]),...(b.data||[])];const connectedIds=[...new Set(rows.map(row=>row.user_a===user.id?row.user_b:row.user_a))];const ids=[...new Set([...connectedIds,...(b.data||[]).map(row=>row.blocked_id)])];let people={};if(ids.length){const result=await supabase.from("profiles").select("id,username,display_name,avatar_url").in("id",ids);if(!result.error)for(const person of result.data||[])people[person.id]=person}const incoming=rows.filter(row=>row.status==="pending"&&row.requested_by!==user.id);const outgoing=rows.filter(row=>row.status==="pending"&&row.requested_by===user.id);const accepted=rows.filter(row=>row.status==="accepted");const card=(row,kind)=>{const id=row.user_a===user.id?row.user_b:row.user_a;const person=people[id]||{};return '<article class="connection-card"><div class="connection-person"><span class="avatar">'+avatarMarkup(person.avatar_url,person.display_name)+'</span><span><strong>'+escapeHTML(person.display_name||"Lumcor member")+'</strong><span>@'+escapeHTML(person.username||"member")+'</span></span></div>'+(kind==="incoming"?'<button class="secondary-button" data-accept="'+row.id+'">Accept</button>':kind==="accepted"?'<button class="secondary-button" data-message="'+id+'">Message</button>':'<span class="request-state">Pending</span>')+'</article>'};$("utilityView").innerHTML='<span class="eyebrow">YOUR PEOPLE</span><h1>Connect</h1><p class="utility-subtitle">Find people by their Lumcor username and build your circle.</p><button class="primary-button" id="connectNewButton">＋ Send a request</button><h3 class="utility-heading">Requests for you</h3>'+(incoming.length?incoming.map(row=>card(row,"incoming")).join(""):'<div class="empty-state"><strong>No incoming requests</strong>New connection requests will appear here.</div>')+'<h3 class="utility-heading">Sent requests</h3>'+(outgoing.length?outgoing.map(row=>card(row,"outgoing")).join(""):'<div class="empty-state compact-empty">No pending requests sent.</div>')+'<h3 class="utility-heading">Your connections</h3>'+(accepted.length?accepted.map(row=>card(row,"accepted")).join(""):'<div class="empty-state compact-empty">Accepted connections will appear here.</div>');$("connectNewButton").addEventListener("click",()=>openCreateModal("direct"));$("utilityView").querySelectorAll("[data-accept]").forEach(button=>button.addEventListener("click",async()=>{const result=await supabase.from("connections").update({status:"accepted"}).eq("id",button.dataset.accept);if(result.error)showToast(result.error.message);else{showToast("Connection accepted");renderConnections()}}));$("utilityView").querySelectorAll("[data-message]").forEach(button=>button.addEventListener("click",()=>createDirectConversation(button.dataset.message).catch(error=>showToast(error.message))))}
async function renderStatus(){if(!online()){$("utilityView").innerHTML='<span class="eyebrow">LIFE IN MOMENTS</span><h1>Status</h1><div class="empty-state"><strong>Status needs internet</strong>Connect to view and publish moments.</div>';return}const result=await supabase.from("statuses").select("id,user_id,text_content,media_path,created_at,expires_at").gt("expires_at",new Date().toISOString()).order("created_at",{ascending:false}).limit(60);if(result.error){showToast(result.error.message);return}const rows=result.data||[];const ids=[...new Set(rows.map(row=>row.user_id))];let people={};if(ids.length){const profiles=await supabase.from("profiles").select("id,display_name,username,avatar_url").in("id",ids);if(!profiles.error)for(const person of profiles.data||[])people[person.id]=person}const statusIds=rows.map(row=>row.id);let likes=[],replies=[],views=[];if(statusIds.length){const [l,r,v]=await Promise.all([supabase.from("status_likes").select("status_id,user_id").in("status_id",statusIds),supabase.from("status_replies").select("id,status_id,user_id,body,created_at").in("status_id",statusIds).order("created_at"),supabase.from("status_views").select("status_id,viewer_id").in("status_id",statusIds)]);if(!l.error)likes=l.data||[];if(!r.error)replies=r.data||[];if(!v.error)views=v.data||[]}statuses=rows.map(row=>({...row,person:people[row.user_id]||{display_name:"Lumcor member"},likes:likes.filter(x=>x.status_id===row.id),replies:replies.filter(x=>x.status_id===row.id),views:views.filter(x=>x.status_id===row.id)}));const media=await Promise.all(statuses.map(async status=>{if(!status.media_path)return null;const {data,error}=await supabase.storage.from("status-media").createSignedUrl(status.media_path,3600);return error?null:data?.signedUrl||null}));const mediaMarkup=(status,index)=>{const url=media[index];if(!url)return "";const video=/\.(mp4|webm|mov)$/i.test(status.media_path||"");return video?'<video class="status-media" src="'+escapeHTML(url)+'" controls playsinline preload="metadata"></video>':'<img class="status-media" src="'+escapeHTML(url)+'" alt="Status photo" loading="lazy">'};const cards=statuses.map((status,index)=>'<article class="status-card status-post"><header class="status-post-head"><div class="avatar">'+avatarMarkup(status.person.avatar_url,status.person.display_name||status.person.username||"L")+'</div><div><strong>'+escapeHTML(status.person.display_name||status.person.username||"Lumcor member")+'</strong><small>'+escapeHTML(new Date(status.created_at).toLocaleString())+'</small></div></header>'+(status.text_content?'<p class="status-copy">'+escapeHTML(status.text_content)+'</p>':'')+mediaMarkup(status,index)+'<div class="status-actions"><button class="secondary-button" data-like-status="'+status.id+'">'+(status.likes.some(x=>x.user_id===user.id)?"♥ Liked":"♡ Like")+' · '+status.likes.length+'</button><button class="secondary-button" data-toggle-replies="'+status.id+'">Replies · '+status.replies.length+'</button>'+(status.user_id===user.id?'<span class="status-view-count">◉ '+status.views.length+' views</span>':'')+'</div><div class="status-replies hidden" id="replies-'+status.id+'">'+(status.replies.map(reply=>'<p><strong>'+escapeHTML(people[reply.user_id]?.display_name||"Lumcor member")+'</strong> '+escapeHTML(reply.body)+'</p>').join("")||'<p class="muted">No replies yet.</p>')+'<form class="status-reply-form" data-reply-form="'+status.id+'"><input class="text-field" name="reply" maxlength="1000" required placeholder="Write a reply"><button class="primary-button" type="submit">Send</button></form></div></article>').join("");$("utilityView").innerHTML='<span class="eyebrow">LIFE IN MOMENTS</span><h1>Status</h1><p class="utility-subtitle">Share photos, videos and updates that disappear after 24 hours.</p><form id="statusComposer" class="status-composer"><textarea class="text-field" id="statusText" maxlength="700" placeholder="What would you like to share?"></textarea><div class="status-compose-tools"><label class="secondary-button status-file-label" for="statusMediaInput">＋ Photo or video</label><input id="statusMediaInput" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime" hidden><span id="statusFileName" class="muted">Optional · up to 50 MB</span><button class="primary-button" id="publishStatus" type="submit">Share status</button></div><div id="statusPreview" class="status-preview"></div></form><div class="status-grid">'+(cards||'<div class="empty-state"><strong>No moments yet</strong>Share your first photo, video or update.</div>')+'</div>';const fileInput=$("statusMediaInput");fileInput.addEventListener("change",()=>{const file=fileInput.files[0];$("statusFileName").textContent=file?file.name:"Optional · up to 50 MB";$("statusPreview").innerHTML="";if(file){const url=URL.createObjectURL(file);$("statusPreview").innerHTML=file.type.startsWith("video/")?'<video class="status-media" src="'+url+'" controls playsinline></video>':'<img class="status-media" src="'+url+'" alt="Selected media preview">'}});$("statusComposer").addEventListener("submit",async event=>{event.preventDefault();const text=$("statusText").value.trim();const file=fileInput.files[0];if(!text&&!file){showToast("Add text, a photo or a video first");return}if(file&&file.size>50*1024*1024){showToast("Choose a file smaller than 50 MB");return}if(file&&!/^(image\/(jpeg|png|webp|gif)|video\/(mp4|webm|quicktime))$/.test(file.type)){showToast("Choose a supported image or video");return}const button=$("publishStatus");button.disabled=true;button.textContent="Publishing…";try{let path=null;if(file){const ext=(file.name.split(".").pop()||"bin").toLowerCase();path=user.id+"/"+crypto.randomUUID()+"."+ext;const upload=await supabase.storage.from("status-media").upload(path,file,{contentType:file.type,upsert:false,cacheControl:"3600"});if(upload.error)throw upload.error}const posted=await supabase.from("statuses").insert({user_id:user.id,text_content:text||null,media_path:path,expires_at:new Date(Date.now()+24*60*60*1000).toISOString()});if(posted.error){if(path)await supabase.storage.from("status-media").remove([path]);throw posted.error}showToast("Status shared");await renderStatus()}catch(error){showToast(error.message||"Status could not be published")}finally{button.disabled=false;button.textContent="Share status"}});$("utilityView").querySelectorAll("[data-like-status]").forEach(button=>button.addEventListener("click",async()=>{const status=statuses.find(x=>x.id===button.dataset.likeStatus);if(!status)return;const liked=status.likes.some(x=>x.user_id===user.id);const result=liked?await supabase.from("status_likes").delete().eq("status_id",status.id).eq("user_id",user.id):await supabase.from("status_likes").insert({status_id:status.id,user_id:user.id});if(result.error){showToast(result.error.message);return}renderStatus()}));$("utilityView").querySelectorAll("[data-toggle-replies]").forEach(button=>button.addEventListener("click",async()=>{const panel=$("replies-"+button.dataset.toggleReplies);panel.classList.toggle("hidden");if(!panel.dataset.viewed){const viewed=await supabase.from("status_views").upsert({status_id:button.dataset.toggleReplies,viewer_id:user.id});if(viewed.error)showToast(viewed.error.message);panel.dataset.viewed="true"}}));$("utilityView").querySelectorAll("[data-reply-form]").forEach(form=>form.addEventListener("submit",async event=>{event.preventDefault();const input=form.elements.reply;const body=input.value.trim();if(!body)return;const result=await supabase.from("status_replies").insert({status_id:form.dataset.replyForm,user_id:user.id,body});if(result.error){showToast(result.error.message);return}showToast("Reply posted");renderStatus()}))}
async function renderMarketplace(){if(!online()){$("utilityView").innerHTML='<div class="marketplace-page"><h1>Marketplace</h1><div class="empty-state">Connect to the internet to browse adverts.</div></div>';return}const result=await supabase.from("marketplace_ads").select("id,owner_id,category,title,description,price_text,destination_url,media_path,media_type,created_at,expires_at").eq("is_active",true).gt("expires_at",new Date().toISOString()).order("created_at",{ascending:false}).limit(100);if(result.error){$("utilityView").innerHTML='<div class="marketplace-page"><h1>Marketplace</h1><div class="empty-state">'+escapeHTML(result.error.message)+'</div></div>';return}marketplaceAds=result.data||[];const ids=[...new Set(marketplaceAds.map(ad=>ad.owner_id))];let people={};if(ids.length){const profiles=await supabase.from("profiles").select("id,display_name,username,avatar_url").in("id",ids);if(!profiles.error)for(const person of profiles.data||[])people[person.id]=person}const cards=marketplaceAds.map(ad=>{const person=people[ad.owner_id]||{};const mediaUrl=ad.media_path?supabase.storage.from("marketplace-media").getPublicUrl(ad.media_path).data.publicUrl:null;let media="";if(mediaUrl){if(ad.media_type==="video")media='<video controls playsinline preload="metadata" src="'+escapeHTML(mediaUrl)+'"></video>';else if(ad.media_type==="audio")media='<audio controls preload="metadata" src="'+escapeHTML(mediaUrl)+'"></audio>';else media='<img loading="lazy" src="'+escapeHTML(mediaUrl)+'" alt="'+escapeHTML(ad.title)+'">'}return '<article class="market-ad-card"><div class="market-ad-owner"><span class="market-avatar">'+avatarMarkup(person.avatar_url,person.display_name)+'</span><span><strong>'+escapeHTML(person.display_name||"Lumcor member")+'</strong><small>'+escapeHTML(ad.category)+' · '+escapeHTML(new Date(ad.created_at).toLocaleDateString())+'</small></span></div>'+(media?'<div class="market-ad-media">'+media+'</div>':"")+'<div class="market-ad-copy"><h3>'+escapeHTML(ad.title)+'</h3>'+(ad.price_text?'<strong class="market-ad-price">'+escapeHTML(ad.price_text)+'</strong>':"")+'<p>'+escapeHTML(ad.description)+'</p>'+(ad.destination_url?'<a class="market-ad-link" href="'+escapeHTML(ad.destination_url)+'" target="_blank" rel="noopener noreferrer">Visit product website ↗</a>':"")+(ad.owner_id===user.id?'<button class="market-delete-ad" data-delete-ad="'+ad.id+'" type="button">Delete advert</button>':'<button class="market-report-ad" data-report-ad="'+ad.id+'" type="button">Report advert</button>')+'</div></article>'});$("utilityView").innerHTML='<div class="marketplace-page"><div class="marketplace-heading"><div><span class="eyebrow">DISCOVER & SHARE</span><h1>Marketplace</h1><p>Explore products and services shared by the Lumcor community.</p></div><button class="primary-button" id="openAdComposer">＋ Advertise a product</button></div><div class="marketplace-notice">Only permitted products and services may be advertised. Restricted or unsafe goods are not allowed. Lumcor does not process payments.</div><form class="market-ad-composer hidden" id="marketAdForm"><h2>Create an advert</h2><label>Product or service title<input class="text-field" id="marketAdTitle" maxlength="90" required placeholder="What are you advertising?"></label><label>Category<select class="text-field" id="marketAdCategory"><option>Clothing & accessories</option><option>Electronics</option><option>Books & learning</option><option>Home & lifestyle</option><option>Creative services</option><option>Other permitted products</option></select></label><label>Description<textarea class="text-field" id="marketAdDescription" maxlength="1200" required placeholder="Describe the product or service"></textarea></label><div class="market-ad-fields"><label>Price (optional)<input class="text-field" id="marketAdPrice" maxlength="60" placeholder="e.g. GHS 120"></label><label>Website or product link (optional)<input class="text-field" id="marketAdUrl" type="url" placeholder="https://example.com"></label></div><label>Photo, video or audio (optional)<input class="text-field" id="marketAdMedia" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime,audio/mpeg,audio/mp4,audio/ogg,audio/wav,audio/webm"></label><small class="market-ad-help">Up to 40 MB. Website links must use HTTPS. Adverts are visible to signed-in Lumcor users.</small><div class="market-ad-form-actions"><button class="secondary-button" id="cancelMarketAd" type="button">Cancel</button><button class="primary-button" id="publishMarketAd" type="submit">Publish advert</button></div><p id="marketAdFeedback" role="status"></p></form><div class="marketplace-feed">'+(cards.join("")||'<div class="empty-state"><strong>No adverts yet</strong>Be the first to share a permitted product or service.</div>')+'</div></div>';$("openAdComposer").addEventListener("click",()=>$("marketAdForm").classList.toggle("hidden"));$("cancelMarketAd").addEventListener("click",()=>$("marketAdForm").classList.add("hidden"));$("marketAdForm").addEventListener("submit",publishMarketplaceAd);$("utilityView").querySelectorAll("[data-report-ad]").forEach(button=>button.addEventListener("click",async()=>{const reason=prompt("Why are you reporting this advert?");if(!reason?.trim())return;const report=await supabase.from("marketplace_ad_reports").insert({ad_id:button.dataset.reportAd,reporter_id:user.id,reason:reason.trim().slice(0,300)});showToast(report.error?report.error.message:"Advert reported for review")}));$("utilityView").querySelectorAll("[data-delete-ad]").forEach(button=>button.addEventListener("click",async()=>{if(!confirm("Delete this advert?"))return;const ad=marketplaceAds.find(item=>item.id===button.dataset.deleteAd);if(!ad)return;const removed=await supabase.from("marketplace_ads").delete().eq("id",ad.id).eq("owner_id",user.id);if(removed.error){showToast(removed.error.message);return}if(ad.media_path)await supabase.storage.from("marketplace-media").remove([ad.media_path]);showToast("Advert deleted");renderMarketplace()}))}
async function publishMarketplaceAd(event){event.preventDefault();const title=$("marketAdTitle").value.trim();const description=$("marketAdDescription").value.trim();const url=$("marketAdUrl").value.trim();const file=$("marketAdMedia").files[0];const feedback=$("marketAdFeedback");const button=$("publishMarketAd");const restricted=/(vape|cigarette|tobacco|alcohol|beer|wine|liquor|marijuana|cannabis|weed|recreational drug|firearm|gun|weapon|knife|ammunition|pornography|sex toy|casino|sports betting|gambling)/i;if(restricted.test(title+" "+description+" "+$("marketAdCategory").value)){feedback.textContent="This category of product or service cannot be advertised on Lumcor.";return}if(title.length<3||description.length<5){feedback.textContent="Add a clear title and description.";return}if(url){try{const parsed=new URL(url);if(parsed.protocol!=="https:")throw new Error()}catch(error){feedback.textContent="Use a valid HTTPS website or product link.";return}}if(file&&file.size>40*1024*1024){feedback.textContent="Choose a media file under 40 MB.";return}const allowed=["image/jpeg","image/png","image/webp","image/gif","video/mp4","video/webm","video/quicktime","audio/mpeg","audio/mp4","audio/ogg","audio/wav","audio/webm"];if(file&&!allowed.includes(file.type)){feedback.textContent="Choose a supported image, video or audio file.";return}button.disabled=true;feedback.textContent="Publishing advert…";let path=null;try{let mediaType=null;if(file){mediaType=file.type.startsWith("image/")?"image":file.type.startsWith("video/")?"video":"audio";const extension=(file.name.split(".").pop()||"dat").toLowerCase().replace(/[^a-z0-9]/g,"");path=user.id+"/"+crypto.randomUUID()+"."+extension;const upload=await supabase.storage.from("marketplace-media").upload(path,file,{contentType:file.type,upsert:false,cacheControl:"3600"});if(upload.error)throw upload.error}const result=await supabase.from("marketplace_ads").insert({owner_id:user.id,category:$("marketAdCategory").value,title,description,price_text:$("marketAdPrice").value.trim()||null,destination_url:url||null,media_path:path,media_type:mediaType}).select("id").single();if(result.error){if(path)await supabase.storage.from("marketplace-media").remove([path]);throw result.error}showToast("Your advert is now published");await renderMarketplace()}catch(error){feedback.textContent=error.message||"Advert could not be published"}finally{button.disabled=false}}
function renderGroups(){const groups=chats.filter(chat=>chat.type==="group");$("utilityView").innerHTML='<span class="eyebrow">YOUR COMMUNITIES</span><h1>Groups</h1><p class="utility-subtitle">Bring conversations together around the things that matter.</p><button class="primary-button" id="createGroupButton">＋ Create a group</button>'+(groups.length?'<div class="status-grid">'+groups.map(chat=>'<article class="status-card"><strong>'+escapeHTML(chat.name)+'</strong><p>'+escapeHTML(chat.about)+'</p><button class="secondary-button" data-open-group="'+chat.id+'">Open group</button><button class="secondary-button" data-add-member="'+chat.id+'">Add member</button></article>').join("")+'</div>':'<div class="empty-state"><strong>No groups yet</strong>Create a group to start a shared conversation.</div>');$("createGroupButton").addEventListener("click",()=>openCreateModal("group"));$("utilityView").querySelectorAll("[data-open-group]").forEach(button=>button.addEventListener("click",()=>openChat(button.dataset.openGroup)));$("utilityView").querySelectorAll("[data-add-member]").forEach(button=>button.addEventListener("click",()=>addGroupMember(button.dataset.addMember)))}
async function addGroupMember(conversationId){const username=prompt("Enter the Lumcor username to add");if(!username)return;const found=await supabase.from("profiles").select("id,display_name").eq("username",username.replace(/^@/,"").toLowerCase()).maybeSingle();if(found.error||!found.data){showToast("Account not found");return}const added=await supabase.from("conversation_members").insert({conversation_id:conversationId,user_id:found.data.id,role:"member"});if(added.error)showToast(added.error.message);else showToast("Member added to group")}
