     <div class="settings-card"><h3>Blocked accounts</h3><p class="settings-help">Blocked people cannot contact you or view your status. They are not notified when you block them.</p><div class="settings-block-row"><select class="text-field" id="blockPersonSelect"><option value="">Choose a connection</option>${people.filter(person=>connectedIds.includes(person.id)&&!blocked.has(person.id)).map(person=>'<option value="'+person.id+'">'+escapeHTML(person.display_name||person.username||"Lumcor member")+'</option>').join("")}</select><button class="danger-button" id="blockPersonButton" type="button">Block</button></div><div class="settings-list">${blockedPeople||'<p class="settings-help">You have not blocked anyone.</p>'}</div></div>
