async function uploadAvatar(event){
 const file=event.target.files?.[0];if(!file)return;
 const feedback=$("profileSettingsFeedback");if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024){feedback.textContent="Choose a JPG, PNG or WebP image under 5 MB.";return}
 const extension=file.type==="image/png"?"png":file.type==="image/webp"?"webp":"jpg";
 const path=user.id+"/"+crypto.randomUUID()+"."+extension;
 feedback.textContent="Uploading profile photo…";
 const upload=await supabase.storage.from("avatars").upload(path,file,{contentType:file.type,cacheControl:"3600"});
 if(upload.error){feedback.textContent=upload.error.message;return}
 const {data}=supabase.storage.from("avatars").getPublicUrl(path);
 const update=await supabase.from("profiles").update({avatar_url:data.publicUrl,updated_at:new Date().toISOString()}).eq("id",user.id).select().single();
 if(update.error){await supabase.storage.from("avatars").remove([path]);feedback.textContent=update.error.message;return}
 profile=update.data;
 $("settingsAvatarPreview").innerHTML=avatarMarkup(profile.avatar_url,profile.display_name);
 $("profileAvatar").innerHTML=avatarMarkup(profile.avatar_url,profile.display_name);
 feedback.textContent="Profile photo updated. It is now visible on your Lumcor profile.";
 await cacheSet("workspace",{chats,profile});
}
async function saveProfileSettings(){
 const displayName=$("settingsDisplayName").value.trim();
 const username=$("settingsUsername").value.trim().toLowerCase().replace(/^@/,"");
 const bio=$("settingsBio").value.trim();
 const feedback=$("profileSettingsFeedback");
 if(displayName.length<2||displayName.length>32){feedback.textContent="Display name must be between 2 and 32 characters.";return}
 if(!/^[a-z0-9_]{3,24}$/.test(username)){feedback.textContent="Username must be 3–24 letters, numbers or underscores.";return}
 feedback.textContent="Saving profile…";
 const result=await supabase.from("profiles").update({display_name:displayName,username,bio,updated_at:new Date().toISOString()}).eq("id",user.id).select().single();
 if(result.error){feedback.textContent=result.error.message;return}
 profile=result.data;
 $("profileName").textContent=profile.display_name;
 $("profileAvatar").innerHTML=avatarMarkup(profile.avatar_url,profile.display_name);
 $("settingsAvatarPreview").innerHTML=avatarMarkup(profile.avatar_url,profile.display_name);
 feedback.textContent="Your profile has been updated.";
 await cacheSet("workspace",{chats,profile});
}
async function saveStatusPrivacy(){
 const ids=[...$("utilityView").querySelectorAll("[data-hidden-user]:checked")].map(input=>input.dataset.hiddenUser);
 const feedback=$("privacyFeedback");feedback.textContent="Saving privacy settings…";
 const removed=await supabase.from("status_hidden_users").delete().eq("owner_id",user.id);
 if(removed.error){feedback.textContent=removed.error.message;return}
 if(ids.length){const inserted=await supabase.from("status_hidden_users").insert(ids.map(id=>({owner_id:user.id,hidden_user_id:id})));if(inserted.error){feedback.textContent=inserted.error.message;return}}
 feedback.textContent="Status privacy saved. The selected people can no longer see your active statuses.";
}
async function blockSelectedPerson(){
 const id=$("blockPersonSelect").value;if(!id){showToast("Choose a connection first");return}
 const result=await supabase.from("user_blocks").insert({blocker_id:user.id,blocked_id:id});
 if(result.error){showToast(result.error.message);return}
 showToast("Account blocked");
 await renderSettings();
}
async function unblockPerson(id){
 const result=await supabase.from("user_blocks").delete().eq("blocker_id",user.id).eq("blocked_id",id);
 if(result.error){showToast(result.error.message);return}
 showToast("Account unblocked");await renderSettings();
}
async function saveConversationPreference(conversationId,field,value){const allowed=["is_muted","is_archived","is_pinned"];if(!allowed.includes(field))return;const payload={user_id:user.id,conversation_id:conversationId,[field]:value,updated_at:new Date().toISOString()};const result=await supabase.from("conversation_preferences").upsert(payload,{onConflict:"user_id,conversation_id"});if(result.error){showToast(result.error.message);return}const chat=chats.find(item=>item.id===conversationId);if(chat)chat[field.replace("is_","")]=value;renderChats();showToast("Conversation preference saved");await cacheSet("workspace",{chats,profile});if(currentView==="settings")await renderSettings()}
async function clearAllChatHistory(){
 if(!confirm("Clear your chat history on this account? Other participants will keep their messages."))return;
 const result=await supabase.from("conversation_members").update({cleared_at:new Date().toISOString()}).eq("user_id",user.id);
 if(result.error){showToast(result.error.message);return}
 await loadChats();showToast("Your chat history has been cleared");
}
async function updateAccountPassword(){
 const password=$("newAccountPassword").value;const confirmation=$("confirmAccountPassword").value;const feedback=$("passwordSettingsFeedback");
 if(password.length<8){feedback.textContent="Password must contain at least 8 characters.";return}
 if(password!==confirmation){feedback.textContent="The passwords do not match.";return}
 feedback.textContent="Updating password…";
 const result=await supabase.auth.updateUser({password});
 if(result.error){feedback.textContent=result.error.message;return}
 $("newAccountPassword").value="";$("confirmAccountPassword").value="";feedback.textContent="Your password has been updated.";
}
async function clearOfflineCache(){
 if(!confirm("Remove cached Lumcor conversations from this browser? Online messages will not be deleted."))return;
 await new Promise(resolve=>{const request=indexedDB.deleteDatabase(CACHE_DB);request.onsuccess=resolve;request.onerror=resolve;request.onblocked=resolve});
 showToast("Offline cache cleared");
}

function toggleTheme(){document.body.classList.toggle("light");try{localStorage.setItem("lumcor.theme",document.body.classList.contains("light")?"light":"dark")}catch(error){}if($("themeButton"))$("themeButton").textContent=document.body.classList.contains("light")?"☾":"☀"}
async function saveSettings(event){event.preventDefault();const displayName=$("displayNameInput").value.trim()||"Lumcor member";const username=$("usernameInput").value.trim().toLowerCase().replace(/^@/,"");if(!/^[a-z0-9_]{3,24}$/.test(username)){showToast("Username must be 3–24 letters, numbers or underscores");return}const result=await supabase.from("profiles").update({display_name:displayName,username,updated_at:new Date().toISOString()}).eq("id",user.id).select().single();if(result.error){showToast(result.error.message);return}profile=result.data;$("profileName").textContent=profile.display_name;$("profileAvatar").textContent=initials(profile.display_name);$("settingsModal").close();await cacheSet("workspace",{chats,profile});showToast("Profile updated")}
async function signOut(){if(realtimeChannel)await supabase.removeChannel(realtimeChannel);await supabase.auth.signOut();user=null;profile=null;session=null;chats=[];activeChatId=null;$("settingsModal").close();showAuth("You have signed out.");setAuthMode("signin")}
async function deleteConversation(){const chat=chats.find(item=>item.id===activeChatId);if(!chat)return;if(!confirm("Remove this conversation from your chat list? Your other participants may still have their copy."))return;const result=await supabase.from("conversation_members").delete().eq("conversation_id",chat.id).eq("user_id",user.id);if(result.error){showToast(result.error.message);return}chats=chats.filter(item=>item.id!==chat.id);await cacheSet("workspace",{chats,profile});showWelcome();showToast("Conversation removed from your account")}
async function init(){$("authModeButton").addEventListener("click",event=>{event.preventDefault();setAuthMode(authMode==="signin"?"signup":"signin")});$("authForm").addEventListener("submit",handleAuth);try{document.body.classList.toggle("light",localStorage.getItem("lumcor.theme")==="light")}catch(error){}if("serviceWorker" in navigator)navigator.serviceWorker.register("./sw.js",{updateViaCache:"none"}).catch(()=>{});setAuthMode("signin");$("sendButton").addEventListener("click",sendMessage);$("messageInput").addEventListener("keydown",event=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();sendMessage()}});$("messageInput").addEventListener("input",event=>{event.target.style.height="auto";event.target.style.height=Math.min(event.target.scrollHeight,120)+"px"});$("searchInput").addEventListener("input",renderChats);$("newChatFilter").addEventListener("click",()=>openCreateModal());document.querySelectorAll("[data-chat-filter]").forEach(button=>button.addEventListener("click",()=>{chatFilter=button.dataset.chatFilter;document.querySelectorAll("[data-chat-filter]").forEach(item=>item.classList.toggle("active",item===button));renderChats()}));$("newChatButton").addEventListener("click",()=>openCreateModal());$("newChatForm").addEventListener("submit",createChat);$("closeNewChatModal").addEventListener("click",()=>$("newChatModal").close());$("cancelNewChatButton").addEventListener("click",()=>$("newChatModal").close());$("newChatModal").addEventListener("click",event=>{if(event.target===$("newChatModal"))$("newChatModal").close()});$("newChatModal").addEventListener("close",()=>{$("newChatFeedback").textContent="";$("createChatButton").disabled=false});$("openSidebar").addEventListener("click",()=>$("sidebar").classList.add("open"));$("closeSidebar").addEventListener("click",()=>$("sidebar").classList.remove("open"));document.querySelectorAll(".rail-button[data-view]").forEach(button=>button.addEventListener("click",()=>{if(button.dataset.view==="chats"){showWelcome();if(window.innerWidth<=680)$("sidebar").classList.add("open")}else showUtility(button.dataset.view)}));$("themeButton").addEventListener("click",toggleTheme);$("settingsButton").addEventListener("click",()=>showUtility("settings"));$("settingsFilterButton").addEventListener("click",event=>{event.preventDefault();event.stopPropagation();$("settingsFilterButton").disabled=true;Promise.resolve(showUtility("settings")).finally(()=>$("settingsFilterButton").disabled=false)});document.querySelectorAll(".mobile-nav-item").forEach(button=>button.addEventListener("click",()=>{if(button.dataset.view==="chats")showWelcome();else showUtility(button.dataset.view)}));$("conversationBack").addEventListener("click",showWelcome);$("profileMenu").addEventListener("click",()=>$("settingsButton").click());$("conversationMenu").addEventListener("click",deleteConversation);$("conversationInfo").addEventListener("click",()=>{const chat=chats.find(item=>item.id===activeChatId);if(chat)showToast(chat.type==="group"?chat.name+" · "+chat.participants.length+" members":chat.about)});$("callButton").addEventListener("click",()=>showToast("Calling is not available yet"));$("attachButton").addEventListener("click",()=>$("attachmentInput").click());$("attachmentInput").addEventListener("change",event=>{const file=event.target.files?.[0];if(file)sendAttachment(file);event.target.value=""});$("stickerButton").addEventListener("click",()=>$("stickerPicker").classList.toggle("hidden"));$("stickerPicker").addEventListener("click",event=>{const button=event.target.closest("[data-sticker]");if(!button)return;sendSticker(button.dataset.sticker);$("stickerPicker").classList.add("hidden")});$("messageActionMenu").addEventListener("click",event=>{const action=event.target.closest("[data-message-action]")?.dataset.messageAction;const message=chats.find(item=>item.id===activeChatId)?.messages.find(item=>item.id===selectedMessageId);$("messageActionMenu").classList.add("hidden");if(action==="me"&&message)deleteMessageForMe(message);if(action==="everyone"&&message?.mine)deleteMessageForEveryone(message);selectedMessageId=null});document.addEventListener("click",event=>{if(!event.target.closest("#messageActionMenu")&&!event.target.closest("[data-message-id]"))$("messageActionMenu").classList.add("hidden")});window.addEventListener("online",()=>{setNetworkStatus();if(user){loadChats().then(subscribeRealtime).catch(()=>{})}});window.addEventListener("offline",()=>{setNetworkStatus();if(realtimeChannel)supabase.removeChannel(realtimeChannel)});try{await loadSupabase()}catch(error){showAuth(error.message||"Lumcor could not load its Lumcor account service.");return}const savedTheme=localStorage.getItem("lumcor.theme");if(savedTheme==="light")document.body.classList.add("light");else document.body.classList.remove("light");$("themeButton").textContent=savedTheme==="light"?"☾":"☀";const {data,error}=await supabase.auth.getSession();if(error){showAuth(error.message);return}session=data.session;user=session?.user||null;if(user){try{if(online()){await ensureProfile()}else{const cached=await cacheGet("workspace");if(!cached?.profile)throw new Error("Connect to the internet once to load this account on this device");profile=cached.profile}await startWorkspace()}catch(problem){showAuth(problem.message||"Could not load your account")}}else{showAuth()}}
init();
